        new Recipe { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nNori\nCorn\nChashu pork", Steps = "1. Simmer broth with miso paste and soy sauce\n2. Cook ramen noodles according to package\n3. Prepare soft-boiled eggs (6.5 minutes)\n4. Slice chashu pork\n5. Assemble bowl: noodles, broth, toppings\n6. Garnish with nori, corn, and green onions" },
