@page "/"

<PageTitle>RecipeHub - Recipe Sharing Community</PageTitle>

<h1>Welcome to RecipeHub 🍽️</h1>
<p class="lead">Discover, share, and rate recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in categories)
    {
        <a href="/recipes/@category.Name.ToLower()" class="category-card">
            <span class="category-icon">@category.Icon</span>
            <h3>@category.Name</h3>
            <p>@category.Description</p>
        </a>
    }
</div>

<div class="cta-section">
    <h2>Got a great recipe?</h2>
    <p>Share your culinary creations with our community!</p>
    <a href="/submit" class="btn btn-primary">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeHub.Models.RecipeCategory> categories = new();

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeHub</PageTitle>

<h1>@categoryDisplay?.Icon @Category Recipes</h1>
<p>@categoryDisplay?.Description</p>

@if (recipes.Any())
{
    <div class="recipe-list">
        @foreach (var recipe in recipes)
        {
            <div class="recipe-card">
                <h3><a href="/recipe/@recipe.Id">@recipe.Title</a></h3>
                <div class="recipe-rating">
                    @if (recipe.RatingCount > 0)
                    {
                        <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                    }
                    else
                    {
                        <span>No ratings yet</span>
                    }
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<p><a href="/">← Back to categories</a></p>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeHub.Models.Recipe> recipes = new();
    private RecipeHub.Models.RecipeCategory? categoryDisplay;

    protected override void OnInitialized()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
        categoryDisplay = RecipeService.GetCategories()
            .FirstOrDefault(c => c.Name.Equals(Category, StringComparison.OrdinalIgnoreCase));
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p class="recipe-category">Category: <a href="/recipes/@recipe.Category.ToLower()">@recipe.Category</a></p>

    <section class="recipe-section">
        <h2>Ingredients</h2>
        <ul>
            @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>Steps</h2>
        @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            <p>@step</p>
        }
    </section>

    <section class="recipe-section">
        <h2>Rate this Recipe</h2>
        <StarRating RecipeId="recipe.Id" />
    </section>
}

<p><a href="/">← Back to categories</a></p>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoverRating > 0 ? hoverRating : currentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hoverRating = star"
              @onmouseout="() => hoverRating = 0">
            ★
        </span>
    }
    @if (submitted)
    {
        <span class="rating-message">Thanks! You rated this @currentRating/5 ⭐</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int currentRating;
    private int hoverRating;
    private bool submitted;

    private void Rate(int stars)
    {
        currentRating = stars;
        submitted = true;
        RecipeService.AddRating(RecipeId, stars);
    }
}

