toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="form-group mb-3">
        <label for="title">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" />
    </div>

    <div class="form-group mb-3">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-control">
            <option value="">-- Select a category --</option>
            @foreach (var cat in categories)
            {
                <option value="@cat.Name">@cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => model.Category" />
    </div>

    <div class="form-group mb-3">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <ValidationMessage For="() => model.Ingredients" />
    </div>

    <div class="form-group mb-3">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. Add wet ingredients" />
        <ValidationMessage For="() => model.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

<p class="mt-3"><a href="/">← Back to home</a></p>

@code {
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel model = new();
    private string? successMessage;
    private List<RecipeHub.Models.RecipeCategory> categories = new();

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var recipe = new RecipeHub.Models.Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };
        RecipeService.AddRecipe(recipe);
        successMessage = $"'{model.Title}' has been submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = string.Empty;
    }
}

